-- 365 Days / 730 Chinese Steamed & Boiled Low-Oil Healthy Meals Database
-- Engine: SQLite3 / Standard SQL Compatible

BEGIN TRANSACTION;
CREATE TABLE daily_summaries (
    day_number INTEGER PRIMARY KEY,
    week_number INTEGER NOT NULL,
    lunch_meal_id INTEGER NOT NULL,
    dinner_meal_id INTEGER NOT NULL,
    lunch_title TEXT NOT NULL,
    dinner_title TEXT NOT NULL,
    lunch_kcal INTEGER NOT NULL,
    dinner_kcal INTEGER NOT NULL,
    total_kcal INTEGER NOT NULL,
    total_protein_g REAL NOT NULL,
    total_carbs_g REAL NOT NULL,
    total_fat_g REAL NOT NULL,
    total_veggies_g REAL NOT NULL,
    note TEXT,
    FOREIGN KEY (lunch_meal_id) REFERENCES meals(id),
    FOREIGN KEY (dinner_meal_id) REFERENCES meals(id)
);
CREATE TABLE dietary_guidelines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topic TEXT NOT NULL,
    rule_content TEXT NOT NULL,
    source_url TEXT
);
CREATE TABLE ingredients (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    category TEXT NOT NULL,            -- 禽肉 / 牛肉 / 猪肉 / 鱼类 / 海鲜 / 豆蛋 / 蔬菜 / 菌菇 / 主食 / 低主食 / 油脂 / 加工肉
    kcal_per_100g REAL NOT NULL,
    protein_per_100g REAL NOT NULL,
    carbs_per_100g REAL NOT NULL,
    fat_per_100g REAL NOT NULL,
    weight_basis TEXT,                 -- 生重 / 熟重 / 蒸熟净重 / 净鱼肉生重 等
    source_note TEXT,
    asset_png TEXT NOT NULL            -- 本地透明图片素材文件名 (/assets/transparent/...)
);
CREATE TABLE meal_ingredients (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    meal_id INTEGER NOT NULL,
    ingredient_id INTEGER,
    ingredient_name TEXT NOT NULL,
    ingredient_category TEXT NOT NULL,
    amount_g REAL NOT NULL,
    kcal_per_100g REAL NOT NULL,
    item_kcal REAL NOT NULL,
    protein_per_100g REAL NOT NULL,
    item_protein_g REAL NOT NULL,
    carbs_per_100g REAL NOT NULL,
    item_carbs_g REAL NOT NULL,
    fat_per_100g REAL NOT NULL,
    item_fat_g REAL NOT NULL,
    FOREIGN KEY (meal_id) REFERENCES meals(id) ON DELETE CASCADE,
    FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)
);
CREATE TABLE meals (
    id INTEGER PRIMARY KEY,            -- 序号 (1..730)
    day_number INTEGER NOT NULL,       -- 第几天 (1..365)
    week_number INTEGER NOT NULL,      -- 周次 (1..53)
    meal_type TEXT NOT NULL,           -- 午餐 / 晚餐
    main_category TEXT NOT NULL,       -- 牛肉 / 禽肉 / 鱼类 / 海鲜 / 猪肉 / 豆蛋 / 加工肉
    title TEXT NOT NULL,               -- 菜单名称 (如：西兰花牛肉口蘑｜糙米饭)
    ingredients_summary TEXT NOT NULL, -- 食材及重量摘要
    staple_food TEXT NOT NULL,         -- 主食名称
    low_carb_tip TEXT,                 -- 低主食调整参考
    seasoning TEXT,                    -- 调味（尽量少盐）
    cooking_method TEXT NOT NULL,      -- 烹调方式 (蒸 / 少油烩 / 炖煮 / 水煮 / 焖煮 等)
    steps TEXT NOT NULL,               -- 单餐步骤
    prep_minutes INTEGER NOT NULL,     -- 备餐分钟
    calories_kcal INTEGER NOT NULL,    -- 估算热量 kcal
    protein_g REAL NOT NULL,           -- 蛋白质 g
    carbs_g REAL NOT NULL,             -- 碳水 g
    fat_g REAL NOT NULL,               -- 脂肪 g
    reminder TEXT,                     -- 提醒
    is_starter_30 INTEGER DEFAULT 0,   -- 是否入选「30道入门精选」
    plate_asset_png TEXT NOT NULL      -- 菜品透明餐盘主图 (/assets/transparent/...)
);
CREATE TABLE weekly_shopping_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    week_number INTEGER NOT NULL,
    ingredient_category TEXT NOT NULL,
    ingredient_name TEXT NOT NULL,
    planned_menu_weight_g REAL NOT NULL,
    estimated_purchase_weight_g REAL NOT NULL,
    purchase_form TEXT,
    note TEXT
);
CREATE INDEX idx_meals_day ON meals(day_number);
CREATE INDEX idx_meals_week ON meals(week_number);
CREATE INDEX idx_meals_category ON meals(main_category);
CREATE INDEX idx_meals_staple ON meals(staple_food);
CREATE INDEX idx_meals_calories ON meals(calories_kcal);
CREATE INDEX idx_meal_ingredients_meal ON meal_ingredients(meal_id);
CREATE INDEX idx_weekly_shopping_week ON weekly_shopping_items(week_number);
DELETE FROM "sqlite_sequence";
COMMIT;
