INSERT INTO "dietary_guidelines" VALUES(1,'总体','原创排列组合，不代表逐道菜来自外部食谱；按可得食材自由替换。',NULL);
INSERT INTO "dietary_guidelines" VALUES(2,'餐盘法','蔬菜约半盘、蛋白质四分之一、谷薯主食四分之一；可按个人需要调整。','https://www.cdc.gov/diabetes/healthy-eating/diabetes-meal-planning.html');
INSERT INTO "dietary_guidelines" VALUES(3,'中国居民膳食指南','建议餐餐有蔬菜，日新鲜蔬菜不少于300g，深色蔬菜占一半；主食应保留，做到食物多样。','https://www.cnsoc.org/bookpublica/0522202019.html');
INSERT INTO "dietary_guidelines" VALUES(4,'油盐添加糖','成年人每日盐<5g，油一般25—30g；少深加工肉，少高盐和添加糖。','https://www.cnsoc.org/bookpublica/0522202019.html');
INSERT INTO "dietary_guidelines" VALUES(5,'成分数据','参考食物成分表及 FoodData Central 的常见食材代表值，均为本表的规划估值；具体标签、部位和烹法会偏离。','https://fdc.nal.usda.gov/food-search/');
INSERT INTO "dietary_guidelines" VALUES(6,'食材称重','禽畜鱼虾及蔬菜：生的可食净重；米饭面条等：熟重；薯类：蒸熟净重；魔芋丝沥水重；蛋去壳重。',NULL);
INSERT INTO "dietary_guidelines" VALUES(7,'调料热量','只把烹调油纳入热量估值；通常5—10g的低盐生抽、少量蚝油及其他调味品未逐一计入；若加入糖/酱汁/坚果请另算。',NULL);
INSERT INTO "dietary_guidelines" VALUES(8,'特殊菜','奥尔良：无糖香辛料自配；照烧：无糖低钠风味，不等于传统含糖照烧酱；火腿和肥牛极少出现。',NULL);
INSERT INTO "dietary_guidelines" VALUES(9,'计算方式','食材明细工作表的每个食材贡献=实际g×每100g估值/100；菜单按每6项求和，热量四舍五入。',NULL);
INSERT INTO "dietary_guidelines" VALUES(10,'提醒','低卡不等于极低碳。两餐总量不等于全天需求，仍应安排早餐、蔬果、奶和其他必要营养。',NULL);
INSERT INTO "dietary_guidelines" VALUES(11,'食物安全','鸡肉/禽肉内部达到74°C；充分煮熟鱼肉、蛋和四季豆；生熟工具分开。','https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures');
INSERT INTO "dietary_guidelines" VALUES(12,'使用','先筛选「730餐菜单」，想看某餐详细原料用「食材明细」菜单编号筛选，采购单按照周次筛选。',NULL);
INSERT INTO "dietary_guidelines" VALUES(13,'更新','若在食材明细里更改用量，菜单宏量值会更新；但菜单的食材文字和预生成采购单不会自动改变。',NULL);
