INSERT INTO "meals" VALUES(1,1,1,'午餐','牛肉','西兰花牛肉口蘑｜糙米饭','瘦牛肉175g、西兰花180g、口蘑130g、糙米饭135g、烹调油5g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；糙米饭另煮熟或蒸好后同餐食用。',30,505,49.3,48.6,14.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_beef.png');
INSERT INTO "meals" VALUES(2,1,1,'晚餐','禽肉','无糖奥尔良鸡排口蘑西兰花｜玉米','鸡胸肉180g、西兰花165g、口蘑135g、玉米125g、烹调油4g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','鸡胸肉拍薄成鸡排；用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；玉米另煮熟或蒸好后同餐食用。',15,451,54.5,43.5,10.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_poultry.png');
INSERT INTO "meals" VALUES(3,2,1,'午餐','禽肉','洋葱鸡腿香菇焖饭｜燕麦饭','去皮鸡腿肉180g、洋葱150g、香菇140g、燕麦饭135g、烹调油4g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','姜片、香菇汁','焖煮','先去皮去骨并切薄，充分加热；食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；燕麦饭另煮熟或蒸好后同餐食用。',30,517,45.1,51.8,16.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_poultry.png');
INSERT INTO "meals" VALUES(4,2,1,'晚餐','牛肉','彩椒牛肉西兰花｜藜麦饭','牛里脊175g、彩椒155g、西兰花170g、藜麦饭140g、烹调油5g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；藜麦饭另煮熟或蒸好后同餐食用。',15,540,49.2,51.2,17.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_beef.png');
INSERT INTO "meals" VALUES(5,3,1,'午餐','牛肉','无糖番茄鸡蛋牛肉烩杂粮饭','瘦牛肉135g、鸡蛋60g、番茄190g、洋葱115g、杂粮饭160g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','番茄丁、黑胡椒','炖煮','番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；杂粮饭另煮熟或蒸好后同餐食用。',35,568,44.1,56.6,18.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_beef.png');
INSERT INTO "meals" VALUES(6,3,1,'晚餐','牛肉','无糖照烧肥牛豆腐乌冬面','肥牛卷95g、北豆腐115g、小白菜180g、口蘑125g、乌冬面135g、烹调油3g','乌冬面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','低盐生抽、米醋、洋葱自然甜味','少油煮','肥牛先汆水撇去浮油；生抽与米醋调汁，不加糖；肉菜加水煮熟后略收汁；面/魔芋丝煮熟后与菜合碗。',25,588,36.8,46.2,29.3,'肥牛油脂高，按份量使用并撇浮油。',1,'plate_beef.png');
INSERT INTO "meals" VALUES(7,4,1,'午餐','加工肉','什锦火腿鸡蛋彩椒口蘑蒸碗｜糙米饭','低盐火腿40g、鸡蛋110g、彩椒160g、口蘑150g、糙米饭120g、烹调油3g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','火腿仅用于提味，另用蛋或豆腐提供蛋白；切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；糙米饭另煮熟或蒸好后同餐食用。',30,460,29.3,46.1,19.5,'加工肉少量点缀；留意包装钠和添加糖。',1,'plate_pork.png');
INSERT INTO "meals" VALUES(8,4,1,'晚餐','鱼类','豉汁清蒸鲈鱼娃娃菜香菇｜紫薯','鲈鱼200g、娃娃菜165g、香菇140g、紫薯120g、烹调油3g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','少量豆豉、姜末','蒸','鱼肉去刺，彻底做熟；豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；紫薯另煮熟或蒸好后同餐食用。',30,427,45.2,40.9,10.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_fish.png');
INSERT INTO "meals" VALUES(9,5,1,'午餐','海鲜','番茄虾仁嫩豆腐小白菜汤｜玉米','虾仁160g、嫩豆腐160g、番茄170g、小白菜160g、玉米125g、烹调油3g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','番茄丁、黑胡椒','炖煮','番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；玉米另煮熟或蒸好后同餐食用。',25,451,46.7,42.6,11.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_seafood.png');
INSERT INTO "meals" VALUES(10,5,1,'晚餐','禽肉','蒜香鸡丝黄瓜木耳｜杂粮饭','鸡胸肉170g、黄瓜160g、泡发木耳150g、杂粮饭120g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','香醋、蒜末、少量生抽','水煮','食材分别煮至熟，淋香醋蒜汁，拌匀即食；杂粮饭另煮熟或蒸好后同餐食用。',15,433,46.2,43.0,10.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_poultry.png');
INSERT INTO "meals" VALUES(11,6,1,'午餐','鱼类','清蒸鳕鱼西兰花口蘑｜紫薯','鳕鱼210g、西兰花190g、口蘑150g、紫薯135g、烹调油4g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','蒜末、白胡椒','蒸','鱼肉去刺，彻底做熟；食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；紫薯另煮熟或蒸好后同餐食用。',25,440,49.9,48.0,7.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_fish.png');
INSERT INTO "meals" VALUES(12,6,1,'晚餐','豆蛋','丝瓜鸡蛋虾仁蒸碗｜荞麦饭','鸡蛋115g、虾仁90g、丝瓜170g、香菇130g、荞麦饭130g、烹调油3g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','鸡蛋先打散成蛋液；切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；荞麦饭另煮熟或蒸好后同餐食用。',20,495,41.0,45.9,17.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_tofu_egg.png');
