INSERT INTO "meals" VALUES(34,17,3,'晚餐','禽肉','豉汁鸡胸肉配秋葵泡发木耳｜杂粮饭','鸡胸肉160g、秋葵160g、泡发木耳140g、杂粮饭110g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；杂粮饭另煮熟或蒸好后同餐食用。',20,435,45.3,46.3,9.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(35,18,3,'午餐','禽肉','椒麻鸡胸肉配四季豆彩椒｜玉米','鸡胸肉155g、四季豆140g、彩椒125g、玉米135g、烹调油5g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','花椒、蒜、少量醋','水煮','花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；玉米另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',25,434,44.0,47.1,10.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
