INSERT INTO "meals" VALUES(57,29,5,'午餐','牛肉','菌菇牛里脊配白萝卜香菇｜紫薯','牛里脊155g、白萝卜140g、香菇110g、紫薯135g、烹调油3g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','姜片、香菇汁','焖煮','食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；紫薯另煮熟或蒸好后同餐食用。',30,419,38.0,42.8,11.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(58,29,5,'晚餐','海鲜','酸汤虾仁配丝瓜白萝卜｜藜麦饭','虾仁175g、丝瓜175g、白萝卜140g、藜麦饭125g、烹调油5g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','米醋、番茄、少许辣椒','水煮','番茄煮成酸汤，主食材汆熟，加入蔬菜再煮2～5分钟；藜麦饭另煮熟或蒸好后同餐食用。',20,413,41.3,39.9,9.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(59,30,5,'午餐','牛肉','咖喱瘦牛肉配竹笋菜心｜米粉','瘦牛肉185g、嫩豆腐160g、竹笋190g、菜心155g、米粉150g、烹调油4g','米粉','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无加糖咖喱粉、姜末','炖煮','用咖喱粉而非高脂咖喱块，加水轻炖主食材和蔬菜；面/魔芋丝煮熟后与菜合碗。',25,603,57.9,54.5,17.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(60,30,5,'晚餐','鱼类','柠檬鲈鱼配西兰花紫甘蓝｜杂粮饭','鲈鱼215g、西兰花190g、紫甘蓝125g、杂粮饭95g、烹调油6g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','柠檬片、白胡椒','蒸','鱼肉去刺，彻底做熟；柠檬片垫底，主食材蒸熟，蔬菜短焯后摆盘；杂粮饭另煮熟或蒸好后同餐食用。',15,492,50.9,44.8,14.4,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(61,31,5,'午餐','加工肉','葱姜清蒸低盐火腿鸡蛋烩芦笋彩椒｜红薯','低盐火腿45g、鸡蛋85g、芦笋190g、彩椒125g、红薯150g、烹调油6g','红薯','想减主食可减到原量2/3，另加100g绿叶菜','葱姜、少量低盐生抽','蒸','火腿仅用于提味，另用蛋或豆腐提供蛋白；切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；红薯另煮熟或蒸好后同餐食用。',20,452,25.2,49.0,19.1,'加工肉少量点缀；留意包装钠和添加糖。',0,'plate_pork.png');
INSERT INTO "meals" VALUES(62,31,5,'晚餐','禽肉','奥尔良风味鸡里脊肉配彩椒香菇｜红薯','鸡里脊肉145g、彩椒160g、香菇110g、红薯115g、烹调油3g','红薯','想减主食可减到原量2/3，另加100g绿叶菜','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；红薯另煮熟或蒸好后同餐食用。',15,368,39.2,40.8,6.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(63,32,5,'午餐','牛肉','柠檬瘦牛肉配大白菜洋葱｜糙米饭','瘦牛肉165g、熟毛豆仁50g、大白菜190g、洋葱125g、糙米饭110g、烹调油6g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','柠檬片、白胡椒','蒸','柠檬片垫底，主食材蒸熟，蔬菜短焯后摆盘；糙米饭另煮熟或蒸好后同餐食用。',30,526,47.7,48.1,16.4,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(64,32,5,'晚餐','鱼类','蒜香巴沙鱼配番茄口蘑｜藜麦饭','巴沙鱼175g、番茄190g、口蘑110g、藜麦饭135g、烹调油4g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','蒜末、白胡椒','蒸','鱼肉去刺，彻底做熟；食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；藜麦饭另煮熟或蒸好后同餐食用。',30,418,40.8,40.0,11.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
