INSERT INTO "meals" VALUES(78,39,6,'晚餐','牛肉','黑椒牛里脊配西葫芦番茄｜全麦面','牛里脊170g、西葫芦140g、番茄155g、全麦面110g、烹调油4g','全麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；面/魔芋丝煮熟后与菜合碗。',15,448,44.3,38.0,14.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(79,40,6,'午餐','鱼类','柠檬三文鱼配丝瓜芦笋｜糙米饭','三文鱼120g、丝瓜175g、芦笋155g、糙米饭110g、烹调油3g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','柠檬片、白胡椒','蒸','鱼肉去刺，彻底做熟；柠檬片垫底，主食材蒸熟，蔬菜短焯后摆盘；糙米饭另煮熟或蒸好后同餐食用。',15,462,32.0,38.9,20.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_fish.png');
INSERT INTO "meals" VALUES(80,40,6,'晚餐','禽肉','清汤去皮鸭胸肉配娃娃菜泡发木耳｜魔芋丝','去皮鸭胸肉180g、娃娃菜175g、泡发木耳110g、魔芋丝130g、烹调油5g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','葱段、盐少量','煮','清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；面/魔芋丝煮熟后与菜合碗。',30,366,38.5,14.5,18.1,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(81,41,6,'午餐','禽肉','椒麻去皮鸭胸肉配荷兰豆莴笋｜山药','去皮鸭胸肉175g、荷兰豆160g、莴笋125g、山药150g、烹调油3g','山药','想减主食可减到原量2/3，另加100g绿叶菜','花椒、蒜、少量醋','水煮','花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；山药另煮熟或蒸好后同餐食用。',30,451,41.2,36.7,16.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(82,41,6,'晚餐','海鲜','蒜香鱿鱼配冬瓜菜心｜红薯','鱿鱼190g、冬瓜140g、菜心110g、红薯135g、烹调油3g','红薯','想减主食可减到原量2/3，另加100g绿叶菜','蒜末、白胡椒','蒸','食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；红薯另煮熟或蒸好后同餐食用。',15,367,37.2,39.5,6.4,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(83,42,6,'午餐','禽肉','豉汁鸡里脊肉配冬瓜口蘑｜杂粮饭','鸡里脊肉155g、冬瓜190g、口蘑140g、杂粮饭135g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；杂粮饭另煮熟或蒸好后同餐食用。',25,426,44.9,42.1,10.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(84,42,6,'晚餐','禽肉','黑椒鸡胸肉配荷兰豆冬瓜｜山药','鸡胸肉170g、熟毛豆仁70g、荷兰豆160g、冬瓜110g、山药125g、烹调油4g','山药','想减主食可减到原量2/3，另加100g绿叶菜','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；山药另煮熟或蒸好后同餐食用。',30,466,54.3,39.2,11.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_poultry.png');
INSERT INTO "meals" VALUES(85,43,7,'午餐','禽肉','清汤去皮鸡腿肉配四季豆泡发木耳｜红薯','去皮鸡腿肉185g、四季豆175g、泡发木耳110g、红薯150g、烹调油5g','红薯','想减主食可减到原量2/3，另加100g绿叶菜','葱段、盐少量','煮','先去皮去骨并切薄，充分加热；清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；红薯另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',30,490,44.2,49.6,14.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(86,43,7,'晚餐','牛肉','葱姜清蒸瘦牛肉配娃娃菜白萝卜｜藜麦饭','瘦牛肉145g、娃娃菜160g、白萝卜155g、藜麦饭125g、烹调油5g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；藜麦饭另煮熟或蒸好后同餐食用。',15,431,39.0,37.6,13.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(87,44,7,'午餐','鱼类','酸汤鳕鱼配大白菜香菇｜乌冬面','鳕鱼200g、大白菜190g、香菇125g、乌冬面135g、烹调油6g','乌冬面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','米醋、番茄、少许辣椒','水煮','鱼肉去刺，彻底做熟；番茄煮成酸汤，主食材汆熟，加入蔬菜再煮2～5分钟；面/魔芋丝煮熟后与菜合碗。',15,461,45.0,48.3,9.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(88,44,7,'晚餐','牛肉','蚝香牛腱子配苦瓜胡萝卜｜糙米饭','牛腱子170g、苦瓜160g、胡萝卜155g、糙米饭80g、烹调油5g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','低钠蚝油少量、姜蒜','少油烩','主食材和蔬菜少油少水烩熟，起锅前点少量蚝油；糙米饭另煮熟或蒸好后同餐食用。',25,467,40.8,40.9,16.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_beef.png');
