INSERT INTO "meals" VALUES(126,63,9,'晚餐','鱼类','椒麻鳕鱼配生菜花菜｜杂粮饭','鳕鱼185g、熟毛豆仁70g、生菜175g、花菜140g、杂粮饭125g、烹调油4g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒、蒜、少量醋','水煮','鱼肉去刺，彻底做熟；花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；杂粮饭另煮熟或蒸好后同餐食用。',20,484,50.8,47.8,11.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
