INSERT INTO "meals" VALUES(149,75,11,'午餐','禽肉','豉汁去皮鸡腿肉配西兰花口蘑｜紫薯','去皮鸡腿肉175g、熟毛豆仁50g、西兰花190g、口蘑140g、紫薯110g、烹调油3g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','少量豆豉、姜末','蒸','先去皮去骨并切薄，充分加热；豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；紫薯另煮熟或蒸好后同餐食用。',15,506,52.4,46.6,15.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(150,75,11,'晚餐','海鲜','豉汁扇贝肉配小白菜口蘑｜荞麦面','扇贝肉170g、小白菜190g、口蘑125g、荞麦面135g、烹调油6g','荞麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；面/魔芋丝煮熟后与菜合碗。',25,409,41.2,42.9,9.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
