INSERT INTO "meals" VALUES(170,85,13,'晚餐','禽肉','清汤去皮鸭胸肉配白萝卜玉米笋｜燕麦饭','去皮鸭胸肉180g、白萝卜140g、玉米笋110g、燕麦饭135g、烹调油6g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱段、盐少量','煮','清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；燕麦饭另煮熟或蒸好后同餐食用。',20,508,41.6,39.3,21.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(171,86,13,'午餐','海鲜','香醋虾仁配黄瓜彩椒｜魔芋丝','虾仁290g、黄瓜160g、彩椒110g、魔芋丝130g、烹调油5g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','香醋、蒜末、少量生抽','水煮','食材分别煮至熟，淋香醋蒜汁，拌匀即食；面/魔芋丝煮熟后与菜合碗。',20,373,57.7,16.2,8.6,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(172,86,13,'晚餐','禽肉','豉汁鸡胸肉配芹菜彩椒｜荞麦饭','鸡胸肉170g、芹菜140g、彩椒155g、荞麦饭110g、烹调油4g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；荞麦饭另煮熟或蒸好后同餐食用。',30,410,45.8,38.6,9.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
