INSERT INTO "meals" VALUES(195,98,14,'午餐','牛肉','剁椒牛里脊配油麦菜口蘑｜糙米饭','牛里脊185g、油麦菜160g、口蘑140g、糙米饭125g、烹调油4g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','自制低盐剁椒、蒜','蒸','主食材铺少量低盐剁椒蒸熟，配菜焯熟后摆盘；糙米饭另煮熟或蒸好后同餐食用。',15,476,48.7,39.0,14.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(196,98,14,'晚餐','海鲜','蒜香虾仁配丝瓜海带｜紫薯','虾仁160g、丝瓜140g、海带110g、紫薯135g、烹调油5g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','蒜末、白胡椒','蒸','食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；紫薯另煮熟或蒸好后同餐食用。',15,373,35.1,41.4,7.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(197,99,15,'午餐','鱼类','菌菇鲈鱼配茼蒿香菇｜藜麦饭','鲈鱼200g、茼蒿190g、香菇125g、藜麦饭165g、烹调油5g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','姜片、香菇汁','焖煮','鱼肉去刺，彻底做熟；食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；藜麦饭另煮熟或蒸好后同餐食用。',25,541,51.6,51.8,15.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(198,99,15,'晚餐','鱼类','酸汤鳕鱼配秋葵泡发木耳｜白米饭','鳕鱼200g、秋葵160g、泡发木耳140g、白米饭80g、烹调油6g','白米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','米醋、番茄、少许辣椒','水煮','鱼肉去刺，彻底做熟；番茄煮成酸汤，主食材汆熟，加入蔬菜再煮2～5分钟；白米饭另煮熟或蒸好后同餐食用。',20,405,43.2,40.9,8.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
