INSERT INTO "meals" VALUES(218,109,16,'晚餐','豆蛋','豉汁北豆腐鸡蛋烩白萝卜彩椒｜红薯','北豆腐300g、鸡蛋85g、白萝卜190g、彩椒155g、红薯110g、烹调油5g','红薯','想减主食可减到原量2/3，另加100g绿叶菜','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；红薯另煮熟或蒸好后同餐食用。',15,610,45.5,46.6,29.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_tofu_egg.png');
INSERT INTO "meals" VALUES(219,110,16,'午餐','牛肉','花椒牛里脊配竹笋金针菇｜米粉','牛里脊175g、竹笋190g、金针菇110g、米粉135g、烹调油3g','米粉','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒粉、姜丝','蒸','薄薄撒花椒和姜丝，蒸至熟透，搭配焯青菜；面/魔芋丝煮熟后与菜合碗。',15,490,47.0,49.3,12.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(220,110,16,'晚餐','海鲜','黑椒花蛤肉配小白菜白萝卜｜杂粮饭','花蛤肉170g、嫩豆腐160g、小白菜175g、白萝卜155g、杂粮饭135g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；杂粮饭另煮熟或蒸好后同餐食用。',25,473,38.0,52.0,13.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(221,111,16,'午餐','猪肉','蚝香猪瘦肉配茼蒿洋葱｜魔芋丝','猪瘦肉155g、茼蒿190g、洋葱110g、魔芋丝130g、烹调油6g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','低钠蚝油少量、姜蒜','少油烩','主食材和蔬菜少油少水烩熟，起锅前点少量蚝油；面/魔芋丝煮熟后与菜合碗。',30,357,36.2,21.0,15.2,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_pork.png');
INSERT INTO "meals" VALUES(222,111,16,'晚餐','鱼类','椒麻鳕鱼配丝瓜金针菇｜藜麦饭','鳕鱼185g、丝瓜175g、金针菇140g、藜麦饭135g、烹调油5g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒、蒜、少量醋','水煮','鱼肉去刺，彻底做熟；花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；藜麦饭另煮熟或蒸好后同餐食用。',15,444,44.3,44.7,9.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(223,112,16,'午餐','鱼类','酸汤鳕鱼配小白菜海带｜糙米饭','鳕鱼215g、小白菜160g、海带155g、糙米饭165g、烹调油5g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','米醋、番茄、少许辣椒','水煮','鱼肉去刺，彻底做熟；番茄煮成酸汤，主食材汆熟，加入蔬菜再煮2～5分钟；糙米饭另煮熟或蒸好后同餐食用。',30,479,47.1,51.0,8.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(224,112,16,'晚餐','禽肉','蒜香去皮鸡腿肉配西葫芦菜心｜全麦面','去皮鸡腿肉160g、嫩豆腐160g、西葫芦140g、菜心140g、全麦面125g、烹调油5g','全麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','蒜末、白胡椒','蒸','先去皮去骨并切薄，充分加热；食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；面/魔芋丝煮熟后与菜合碗。',30,540,50.7,43.7,19.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
