INSERT INTO "meals" VALUES(241,121,18,'午餐','鱼类','蒜香鳕鱼配花菜金针菇｜藜麦饭','鳕鱼215g、花菜140g、金针菇140g、藜麦饭110g、烹调油4g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','蒜末、白胡椒','蒸','鱼肉去刺，彻底做熟；食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；藜麦饭另煮熟或蒸好后同餐食用。',30,431,49.7,39.4,8.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(242,121,18,'晚餐','海鲜','葱姜清蒸虾仁配生菜莴笋｜白米饭','虾仁175g、生菜175g、莴笋155g、白米饭80g、烹调油6g','白米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；白米饭另煮熟或蒸好后同餐食用。',15,356,39.3,30.6,8.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(243,122,18,'午餐','鱼类','清汤巴沙鱼配芦笋菜心｜燕麦饭','巴沙鱼175g、芦笋140g、菜心125g、燕麦饭135g、烹调油5g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱段、盐少量','煮','鱼肉去刺，彻底做熟；清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；燕麦饭另煮熟或蒸好后同餐食用。',25,404,39.7,38.2,12.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
