INSERT INTO "meals" VALUES(248,124,18,'晚餐','豆蛋','番茄鸡蛋嫩豆腐烩番茄花菜｜糙米饭','鸡蛋120g、嫩豆腐160g、番茄190g、花菜155g、糙米饭125g、烹调油5g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','番茄丁、黑胡椒','炖煮','鸡蛋先打散成蛋液；番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；糙米饭另煮熟或蒸好后同餐食用。',25,523,31.7,49.3,23.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_tofu_egg.png');
