INSERT INTO "meals" VALUES(279,140,20,'午餐','禽肉','奥尔良风味去皮鸡腿肉配彩椒口蘑｜糙米饭','去皮鸡腿肉185g、彩椒160g、口蘑140g、糙米饭110g、烹调油6g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','先去皮去骨并切薄，充分加热；用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；糙米饭另煮熟或蒸好后同餐食用。',15,482,45.8,40.2,17.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
