INSERT INTO "meals" VALUES(311,156,23,'午餐','禽肉','豉汁鸡胸肉配大白菜口蘑｜玉米','鸡胸肉165g、大白菜140g、口蘑125g、玉米150g、烹调油5g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；玉米另煮熟或蒸好后同餐食用。',25,435,49.0,41.6,11.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(312,156,23,'晚餐','鱼类','番茄鲈鱼配菜心｜土豆','鲈鱼200g、番茄190g、菜心110g、土豆95g、烹调油3g','土豆','想减主食可减到原量2/3，另加100g绿叶菜','番茄丁、黑胡椒','炖煮','鱼肉去刺，彻底做熟；番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；土豆另煮熟或蒸好后同餐食用。',25,371,43.8,27.8,9.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(313,157,23,'午餐','鱼类','葱姜清蒸巴沙鱼配四季豆紫甘蓝｜乌冬面','巴沙鱼185g、四季豆175g、紫甘蓝125g、乌冬面125g、烹调油3g','乌冬面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','鱼肉去刺，彻底做熟；切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；面/魔芋丝煮熟后与菜合碗。四季豆必须充分煮熟，不要生脆。',20,437,39.5,52.6,8.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
