INSERT INTO "meals" VALUES(337,169,25,'午餐','鱼类','清汤鳕鱼配芹菜紫甘蓝｜山药','鳕鱼215g、芹菜140g、紫甘蓝155g、山药140g、烹调油3g','山药','想减主食可减到原量2/3，另加100g绿叶菜','葱段、盐少量','煮','鱼肉去刺，彻底做熟；清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；山药另煮熟或蒸好后同餐食用。',25,368,44.4,36.0,5.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
