INSERT INTO "meals" VALUES(357,179,26,'午餐','鱼类','椒麻鲈鱼配生菜荷兰豆｜紫薯','鲈鱼215g、生菜160g、荷兰豆140g、紫薯165g、烹调油6g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','花椒、蒜、少量醋','水煮','鱼肉去刺，彻底做熟；花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；紫薯另煮熟或蒸好后同餐食用。',25,521,49.7,51.4,13.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(358,179,26,'晚餐','禽肉','香醋去皮鸡腿肉配西葫芦洋葱｜荞麦面','去皮鸡腿肉180g、西葫芦160g、洋葱125g、荞麦面135g、烹调油4g','荞麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','香醋、蒜末、少量生抽','水煮','先去皮去骨并切薄，充分加热；食材分别煮至熟，淋香醋蒜汁，拌匀即食；面/魔芋丝煮熟后与菜合碗。',15,480,44.7,44.9,14.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(359,180,26,'午餐','禽肉','剁椒去皮鸡腿肉配四季豆杏鲍菇｜藜麦饭','去皮鸡腿肉185g、四季豆175g、杏鲍菇110g、藜麦饭150g、烹调油5g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','自制低盐剁椒、蒜','蒸','先去皮去骨并切薄，充分加热；主食材铺少量低盐剁椒蒸熟，配菜焯熟后摆盘；藜麦饭另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',25,549,49.0,52.3,17.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(360,180,26,'晚餐','牛肉','椒麻肥牛卷北豆腐烩荷兰豆小白菜｜藜麦饭','肥牛卷85g、北豆腐90g、荷兰豆190g、小白菜155g、藜麦饭110g、烹调油3g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒、蒜、少量醋','水煮','肥牛先汆水撇去浮油；花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；藜麦饭另煮熟或蒸好后同餐食用。',25,559,35.2,44.7,27.5,'肥牛油脂高，按份量使用并撇浮油。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(361,181,26,'午餐','鱼类','葱姜清蒸鲈鱼配花菜海带｜荞麦面','鲈鱼215g、熟毛豆仁50g、花菜175g、海带155g、荞麦面165g、烹调油6g','荞麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','鱼肉去刺，彻底做熟；切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；面/魔芋丝煮熟后与菜合碗。',25,596,58.5,55.7,16.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(362,181,26,'晚餐','海鲜','蒜香扇贝肉配芦笋白萝卜｜糙米饭','扇贝肉170g、芦笋175g、白萝卜140g、糙米饭135g、烹调油5g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','蒜末、白胡椒','蒸','食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；糙米饭另煮熟或蒸好后同餐食用。',15,409,37.1,49.3,7.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
