INSERT INTO "meals" VALUES(365,183,27,'午餐','海鲜','菌菇花蛤肉配茼蒿口蘑｜山药','花蛤肉190g、嫩豆腐135g、茼蒿160g、口蘑140g、山药125g、烹调油3g','山药','想减主食可减到原量2/3，另加100g绿叶菜','姜片、香菇汁','焖煮','食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；山药另煮熟或蒸好后同餐食用。',30,390,40.7,38.5,9.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(366,183,27,'晚餐','禽肉','奥尔良风味鸡胸肉配彩椒口蘑｜玉米','鸡胸肉170g、北豆腐130g、彩椒140g、口蘑110g、玉米135g、烹调油3g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','鸡胸肉拍薄成鸡排；用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；玉米另煮熟或蒸好后同餐食用。',20,535,61.5,44.5,15.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(367,184,27,'午餐','海鲜','黑椒虾仁配生菜紫甘蓝｜魔芋丝','虾仁250g、生菜190g、紫甘蓝140g、魔芋丝200g、烹调油6g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；面/魔芋丝煮熟后与菜合碗。',25,371,52.7,20.7,9.1,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_seafood.png');
