INSERT INTO "meals" VALUES(378,189,27,'晚餐','鱼类','酸汤鳕鱼配娃娃菜白萝卜｜燕麦饭','鳕鱼200g、娃娃菜140g、白萝卜140g、燕麦饭95g、烹调油4g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','米醋、番茄、少许辣椒','水煮','鱼肉去刺，彻底做熟；番茄煮成酸汤，主食材汆熟，加入蔬菜再煮2～5分钟；燕麦饭另煮熟或蒸好后同餐食用。',25,360,41.7,29.8,7.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(379,190,28,'午餐','禽肉','葱姜清蒸去皮鸭胸肉配芹菜海带｜魔芋丝','去皮鸭胸肉165g、芹菜190g、海带155g、魔芋丝130g、烹调油6g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','葱姜、少量低盐生抽','蒸','切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；面/魔芋丝煮熟后与菜合碗。',25,368,35.2,17.0,17.9,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(380,190,28,'晚餐','禽肉','奥尔良风味去皮鸡腿肉配西葫芦口蘑｜全麦面','去皮鸡腿肉180g、西葫芦175g、口蘑110g、全麦面135g、烹调油5g','全麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','先去皮去骨并切薄，充分加热；用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；面/魔芋丝煮熟后与菜合碗。',15,491,48.3,42.8,16.4,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(381,191,28,'午餐','猪肉','清汤猪瘦肉配生菜香菇｜燕麦饭','猪瘦肉165g、生菜160g、香菇155g、燕麦饭125g、烹调油3g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱段、盐少量','煮','清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；燕麦饭另煮熟或蒸好后同餐食用。',30,457,42.7,41.4,15.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_pork.png');
INSERT INTO "meals" VALUES(382,191,28,'晚餐','牛肉','椒麻牛腱子配西兰花洋葱｜紫薯','牛腱子145g、西兰花175g、洋葱140g、紫薯110g、烹调油5g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','花椒、蒜、少量醋','水煮','花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；紫薯另煮熟或蒸好后同餐食用。',30,468,38.7,49.5,14.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(383,192,28,'午餐','牛肉','咖喱瘦牛肉配娃娃菜莴笋｜糙米饭','瘦牛肉185g、娃娃菜160g、莴笋125g、糙米饭135g、烹调油3g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无加糖咖喱粉、姜末','炖煮','用咖喱粉而非高脂咖喱块，加水轻炖主食材和蔬菜；糙米饭另煮熟或蒸好后同餐食用。',20,455,45.7,40.0,12.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(384,192,28,'晚餐','禽肉','豉汁去皮鸡腿肉配油麦菜荷兰豆｜燕麦饭','去皮鸡腿肉180g、油麦菜140g、荷兰豆140g、燕麦饭135g、烹调油6g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','先去皮去骨并切薄，充分加热；豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；燕麦饭另煮熟或蒸好后同餐食用。',20,512,46.2,43.2,18.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(385,193,28,'午餐','禽肉','豉汁鸡胸肉配油麦菜玉米笋｜山药','鸡胸肉165g、油麦菜160g、玉米笋110g、山药135g、烹调油5g','山药','想减主食可减到原量2/3，另加100g绿叶菜','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；山药另煮熟或蒸好后同餐食用。',20,368,44.4,29.4,8.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(386,193,28,'晚餐','豆蛋','香醋嫩豆腐虾仁烩西葫芦菜心｜红薯','嫩豆腐300g、虾仁65g、西葫芦190g、菜心155g、红薯135g、烹调油3g','红薯','想减主食可减到原量2/3，另加100g绿叶菜','香醋、蒜末、少量生抽','水煮','食材分别煮至熟，淋香醋蒜汁，拌匀即食；红薯另煮熟或蒸好后同餐食用。',30,433,34.9,45.3,13.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_tofu_egg.png');
