INSERT INTO "meals" VALUES(388,194,28,'晚餐','鱼类','菌菇鳕鱼配丝瓜香菇｜玉米','鳕鱼200g、丝瓜140g、香菇125g、玉米95g、烹调油5g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','姜片、香菇汁','焖煮','鱼肉去刺，彻底做熟；食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；玉米另煮熟或蒸好后同餐食用。',20,385,43.4,35.0,8.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(389,195,28,'午餐','海鲜','黑椒虾仁配四季豆紫甘蓝｜燕麦饭','虾仁160g、四季豆140g、紫甘蓝155g、燕麦饭110g、烹调油5g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；燕麦饭另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',20,401,38.6,44.9,9.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(390,195,28,'晚餐','海鲜','清汤扇贝肉配丝瓜白萝卜｜土豆','扇贝肉170g、丝瓜190g、白萝卜155g、土豆160g、烹调油3g','土豆','想减主食可减到原量2/3，另加100g绿叶菜','葱段、盐少量','煮','清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；土豆另煮熟或蒸好后同餐食用。',25,371,34.9,46.4,5.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(391,196,28,'午餐','禽肉','蚝香去皮鸡腿肉配紫甘蓝白萝卜｜米粉','去皮鸡腿肉175g、紫甘蓝160g、白萝卜110g、米粉150g、烹调油5g','米粉','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','低钠蚝油少量、姜蒜','少油烩','先去皮去骨并切薄，充分加热；主食材和蔬菜少油少水烩熟，起锅前点少量蚝油；面/魔芋丝煮熟后与菜合碗。',15,498,40.9,52.1,14.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
