INSERT INTO "meals" VALUES(401,201,29,'午餐','牛肉','孜然瘦牛肉配番茄泡发木耳｜米粉','瘦牛肉175g、番茄140g、泡发木耳140g、米粉110g、烹调油6g','米粉','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','孜然、辣椒粉、蒜末','少油焖','主食材用少量油和水焖熟，下蔬菜翻拌，撒孜然；面/魔芋丝煮熟后与菜合碗。',20,457,42.3,40.4,13.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(402,201,29,'晚餐','禽肉','无糖照烧去皮鸡腿肉配西兰花洋葱｜乌冬面','去皮鸡腿肉145g、北豆腐130g、西兰花190g、洋葱110g、乌冬面80g、烹调油5g','乌冬面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','低盐生抽、米醋、洋葱自然甜味','少油煮','先去皮去骨并切薄，充分加热；生抽与米醋调汁，不加糖；肉菜加水煮熟后略收汁；面/魔芋丝煮熟后与菜合碗。',15,548,50.5,46.1,20.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(403,202,29,'午餐','禽肉','奥尔良风味鸡里脊肉配西兰花洋葱｜藜麦饭','鸡里脊肉165g、西兰花190g、洋葱155g、藜麦饭150g、烹调油3g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；藜麦饭另煮熟或蒸好后同餐食用。',30,515,51.6,59.7,9.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(404,202,29,'晚餐','海鲜','酸汤虾仁配菜心冬瓜｜白米饭','虾仁160g、熟毛豆仁70g、菜心160g、冬瓜140g、白米饭80g、烹调油5g','白米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','米醋、番茄、少许辣椒','水煮','番茄煮成酸汤，主食材汆熟，加入蔬菜再煮2～5分钟；白米饭另煮熟或蒸好后同餐食用。',20,416,44.6,37.2,11.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(405,203,29,'午餐','鱼类','菌菇鲈鱼配生菜杏鲍菇｜魔芋丝','鲈鱼215g、生菜190g、杏鲍菇140g、魔芋丝160g、烹调油6g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','姜片、香菇汁','焖煮','鱼肉去刺，彻底做熟；食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；面/魔芋丝煮熟后与菜合碗。',35,374,46.8,19.1,13.1,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(406,203,29,'晚餐','牛肉','豉汁牛里脊配荷兰豆彩椒｜土豆','牛里脊180g、荷兰豆160g、彩椒125g、土豆80g、烹调油5g','土豆','想减主食可减到原量2/3，另加100g绿叶菜','少量豆豉、姜末','蒸','豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；土豆另煮熟或蒸好后同餐食用。',15,442,45.1,33.4,14.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(407,204,30,'午餐','牛肉','椒麻瘦牛肉配四季豆芦笋｜藜麦饭','瘦牛肉185g、熟毛豆仁70g、四季豆190g、芦笋140g、藜麦饭165g、烹调油6g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒、蒜、少量醋','水煮','花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；藜麦饭另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',15,654,61.0,60.2,20.4,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
