INSERT INTO "meals" VALUES(425,213,31,'午餐','禽肉','剁椒去皮鸡腿肉配娃娃菜杏鲍菇｜荞麦饭','去皮鸡腿肉175g、娃娃菜160g、杏鲍菇155g、荞麦饭110g、烹调油6g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','自制低盐剁椒、蒜','蒸','先去皮去骨并切薄，充分加热；主食材铺少量低盐剁椒蒸熟，配菜焯熟后摆盘；荞麦饭另煮熟或蒸好后同餐食用。',20,475,43.9,40.5,16.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
