INSERT INTO "meals" VALUES(427,214,31,'午餐','牛肉','蒜香瘦牛肉配四季豆绿豆芽｜紫薯','瘦牛肉165g、熟毛豆仁70g、四季豆160g、绿豆芽110g、紫薯165g、烹调油3g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','蒜末、白胡椒','蒸','食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；紫薯另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',20,558,51.9,60.4,13.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
