INSERT INTO "meals" VALUES(448,224,32,'晚餐','鱼类','豉汁巴沙鱼配生菜口蘑｜白米饭','巴沙鱼185g、生菜140g、口蘑110g、白米饭135g、烹调油5g','白米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','鱼肉去刺，彻底做熟；豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；白米饭另煮熟或蒸好后同餐食用。',30,415,40.3,42.3,10.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
