INSERT INTO "meals" VALUES(469,235,34,'午餐','禽肉','孜然去皮鸡腿肉配丝瓜金针菇｜荞麦饭','去皮鸡腿肉155g、丝瓜175g、金针菇155g、荞麦饭110g、烹调油5g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','孜然、辣椒粉、蒜末','少油焖','先去皮去骨并切薄，充分加热；主食材用少量油和水焖熟，下蔬菜翻拌，撒孜然；荞麦饭另煮熟或蒸好后同餐食用。',25,444,40.2,41.1,14.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
