INSERT INTO "meals" VALUES(471,236,34,'午餐','禽肉','奥尔良风味去皮鸡腿肉配芦笋洋葱｜紫薯','去皮鸡腿肉185g、嫩豆腐135g、芦笋190g、洋葱125g、紫薯150g、烹调油3g','紫薯','想减主食可减到原量2/3，另加100g绿叶菜','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','先去皮去骨并切薄，充分加热；用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；紫薯另煮熟或蒸好后同餐食用。',15,563,51.7,54.7,16.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(472,236,34,'晚餐','海鲜','菌菇鱿鱼配四季豆杏鲍菇｜全麦面','鱿鱼160g、四季豆140g、杏鲍菇140g、全麦面80g、烹调油3g','全麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','姜片、香菇汁','焖煮','食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；面/魔芋丝煮熟后与菜合碗。四季豆必须充分煮熟，不要生脆。',25,371,36.5,43.4,6.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(473,237,34,'午餐','鱼类','柠檬三文鱼配荷兰豆口蘑｜燕麦饭','三文鱼135g、荷兰豆160g、口蘑155g、燕麦饭150g、烹调油2g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','柠檬片、白胡椒','蒸','鱼肉去刺，彻底做熟；柠檬片垫底，主食材蒸熟，蔬菜短焯后摆盘；燕麦饭另煮熟或蒸好后同餐食用。',15,561,41.1,48.6,23.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(474,237,34,'晚餐','牛肉','剁椒瘦牛肉配花菜芦笋｜糙米饭','瘦牛肉170g、花菜190g、芦笋140g、糙米饭110g、烹调油6g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','自制低盐剁椒、蒜','蒸','主食材铺少量低盐剁椒蒸熟，配菜焯熟后摆盘；糙米饭另煮熟或蒸好后同餐食用。',25,465,45.4,40.8,14.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_beef.png');
INSERT INTO "meals" VALUES(475,238,34,'午餐','鱼类','清汤鲈鱼配菜心白萝卜｜玉米','鲈鱼175g、菜心190g、白萝卜155g、玉米165g、烹调油5g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','葱段、盐少量','煮','鱼肉去刺，彻底做熟；清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；玉米另煮熟或蒸好后同餐食用。',25,468,43.6,49.2,13.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(476,238,34,'晚餐','禽肉','蚝香去皮鸡腿肉配西葫芦玉米笋｜糙米饭','去皮鸡腿肉160g、西葫芦160g、玉米笋140g、糙米饭95g、烹调油6g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','低钠蚝油少量、姜蒜','少油烩','先去皮去骨并切薄，充分加热；主食材和蔬菜少油少水烩熟，起锅前点少量蚝油；糙米饭另煮熟或蒸好后同餐食用。',25,424,39.2,34.2,15.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
