INSERT INTO "meals" VALUES(478,239,35,'晚餐','海鲜','蒜香鱿鱼配冬瓜胡萝卜｜魔芋丝','鱿鱼265g、冬瓜140g、胡萝卜110g、魔芋丝160g、烹调油5g','魔芋丝','魔芋丝不是完整主食；饥饿可补杂粮饭或蒸薯类','蒜末、白胡椒','蒸','食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；面/魔芋丝煮熟后与菜合碗。',15,374,47.1,23.7,9.2,'调料尽量低盐，不加白砂糖；油重已计入热量。魔芋丝低能量，不等于一份主食。',0,'plate_seafood.png');
