INSERT INTO "meals" VALUES(655,328,47,'午餐','海鲜','葱姜清蒸虾仁配菠菜口蘑｜燕麦饭','虾仁175g、菠菜190g、口蘑140g、燕麦饭110g、烹调油5g','燕麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；燕麦饭另煮熟或蒸好后同餐食用。',25,398,46.6,35.3,10.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
