INSERT INTO "meals" VALUES(677,339,49,'午餐','猪肉','花椒猪里脊配苦瓜泡发木耳｜杂粮饭','猪里脊155g、苦瓜175g、泡发木耳140g、杂粮饭125g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒粉、姜丝','蒸','薄薄撒花椒和姜丝，蒸至熟透，搭配焯青菜；杂粮饭另煮熟或蒸好后同餐食用。',20,443,40.3,45.0,12.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_pork.png');
INSERT INTO "meals" VALUES(678,339,49,'晚餐','鱼类','蒜香巴沙鱼配芹菜小白菜｜土豆','巴沙鱼175g、芹菜190g、小白菜125g、土豆170g、烹调油3g','土豆','想减主食可减到原量2/3，另加100g绿叶菜','蒜末、白胡椒','蒸','鱼肉去刺，彻底做熟；食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；土豆另煮熟或蒸好后同餐食用。',30,371,37.1,39.4,7.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(679,340,49,'午餐','猪肉','花椒猪瘦肉配大白菜绿豆芽｜糙米饭','猪瘦肉175g、大白菜140g、绿豆芽125g、糙米饭125g、烹调油6g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒粉、姜丝','蒸','薄薄撒花椒和姜丝，蒸至熟透，搭配焯青菜；糙米饭另煮熟或蒸好后同餐食用。',30,484,44.1,41.4,17.2,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_pork.png');
