INSERT INTO "meals" VALUES(681,341,49,'午餐','猪肉','咖喱猪里脊配荷兰豆杏鲍菇｜山药','猪里脊165g、荷兰豆160g、杏鲍菇125g、山药110g、烹调油5g','山药','想减主食可减到原量2/3，另加100g绿叶菜','无加糖咖喱粉、姜末','炖煮','用咖喱粉而非高脂咖喱块，加水轻炖主食材和蔬菜；山药另煮熟或蒸好后同餐食用。',30,422,43.3,36.8,11.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_pork.png');
INSERT INTO "meals" VALUES(682,341,49,'晚餐','禽肉','孜然鸡胸肉配小白菜口蘑｜藜麦饭','鸡胸肉170g、小白菜175g、口蘑125g、藜麦饭135g、烹调油4g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','孜然、辣椒粉、蒜末','少油焖','主食材用少量油和水焖熟，下蔬菜翻拌，撒孜然；藜麦饭另煮熟或蒸好后同餐食用。',15,442,51.7,37.8,10.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(683,342,49,'午餐','海鲜','蒜香虾仁配花菜小白菜｜荞麦面','虾仁190g、花菜190g、小白菜140g、荞麦面165g、烹调油5g','荞麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','蒜末、白胡椒','蒸','食材切块，撒蒜末；上锅蒸熟，蔬菜另焯后拌匀；面/魔芋丝煮熟后与菜合碗。',25,461,48.7,48.8,9.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_seafood.png');
INSERT INTO "meals" VALUES(684,342,49,'晚餐','禽肉','黑椒去皮鸡腿肉配秋葵口蘑｜杂粮饭','去皮鸡腿肉180g、秋葵190g、口蘑125g、杂粮饭110g、烹调油3g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','先去皮去骨并切薄，充分加热；锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；杂粮饭另煮熟或蒸好后同餐食用。',30,469,46.9,44.2,14.0,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
