INSERT INTO "meals" VALUES(687,344,50,'午餐','鱼类','剁椒巴沙鱼配紫甘蓝小白菜｜杂粮饭','巴沙鱼215g、紫甘蓝175g、小白菜155g、杂粮饭110g、烹调油5g','杂粮饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','自制低盐剁椒、蒜','蒸','鱼肉去刺，彻底做熟；主食材铺少量低盐剁椒蒸熟，配菜焯熟后摆盘；杂粮饭另煮熟或蒸好后同餐食用。',20,446,44.9,43.0,11.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(688,344,50,'晚餐','禽肉','番茄去皮鸭胸肉配海带｜土豆','去皮鸭胸肉145g、番茄190g、海带155g、土豆135g、烹调油6g','土豆','想减主食可减到原量2/3，另加100g绿叶菜','番茄丁、黑胡椒','炖煮','番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；土豆另煮熟或蒸好后同餐食用。',30,439,33.5,38.6,16.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(689,345,50,'午餐','鱼类','豉汁鲈鱼配西兰花金针菇｜白米饭','鲈鱼215g、西兰花175g、金针菇155g、白米饭135g、烹调油5g','白米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','少量豆豉、姜末','蒸','鱼肉去刺，彻底做熟；豆豉冲洗剁碎，与姜末拌主食材后蒸熟；蔬菜另煮；白米饭另煮熟或蒸好后同餐食用。',25,536,53.0,56.7,12.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
INSERT INTO "meals" VALUES(690,345,50,'晚餐','禽肉','黑椒去皮鸡腿肉配四季豆胡萝卜｜荞麦饭','去皮鸡腿肉180g、四季豆140g、胡萝卜155g、荞麦饭110g、烹调油6g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','黑胡椒、蒜末','少油烩','先去皮去骨并切薄，充分加热；锅加少量水和油，先把主食材煮熟，再烩两种蔬菜，收汁撒黑椒；荞麦饭另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',25,507,43.7,49.5,16.7,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
