INSERT INTO "meals" VALUES(721,361,52,'午餐','禽肉','番茄去皮鸡腿肉配西兰花｜荞麦饭','去皮鸡腿肉185g、番茄175g、西兰花110g、荞麦饭165g、烹调油5g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','番茄丁、黑胡椒','炖煮','先去皮去骨并切薄，充分加热；番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；荞麦饭另煮熟或蒸好后同餐食用。',35,530,47.3,51.0,16.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(722,361,52,'晚餐','牛肉','咖喱牛里脊配西葫芦冬瓜｜荞麦饭','牛里脊145g、西葫芦160g、冬瓜110g、荞麦饭110g、烹调油5g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无加糖咖喱粉、姜末','炖煮','用咖喱粉而非高脂咖喱块，加水轻炖主食材和蔬菜；荞麦饭另煮熟或蒸好后同餐食用。',20,396,36.6,32.5,13.9,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(723,362,52,'午餐','海鲜','柠檬鱿鱼配四季豆小白菜｜玉米','鱿鱼190g、四季豆175g、小白菜125g、玉米135g、烹调油4g','玉米','想减主食可减到原量2/3，另加100g绿叶菜','柠檬片、白胡椒','蒸','柠檬片垫底，主食材蒸熟，蔬菜短焯后摆盘；玉米另煮熟或蒸好后同餐食用。四季豆必须充分煮熟，不要生脆。',20,434,42.0,49.3,9.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(724,362,52,'晚餐','豆蛋','香醋鸡蛋嫩豆腐烩芦笋娃娃菜｜藜麦饭','鸡蛋120g、嫩豆腐110g、芦笋140g、娃娃菜110g、藜麦饭110g、烹调油6g','藜麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','香醋、蒜末、少量生抽','水煮','鸡蛋先打散成蛋液；食材分别煮至熟，淋香醋蒜汁，拌匀即食；藜麦饭另煮熟或蒸好后同餐食用。',20,466,30.5,35.7,23.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',1,'plate_tofu_egg.png');
INSERT INTO "meals" VALUES(725,363,52,'午餐','豆蛋','番茄北豆腐熟毛豆仁烩番茄玉米笋｜土豆','北豆腐300g、熟毛豆仁70g、番茄140g、玉米笋155g、土豆110g、烹调油4g','土豆','想减主食可减到原量2/3，另加100g绿叶菜','番茄丁、黑胡椒','炖煮','番茄出汁后加入主食材和少量水，轻炖至熟，再放配菜；土豆另煮熟或蒸好后同餐食用。',35,544,45.0,44.4,23.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_tofu_egg.png');
INSERT INTO "meals" VALUES(726,363,52,'晚餐','禽肉','奥尔良风味鸡里脊肉配西兰花洋葱｜荞麦饭','鸡里脊肉170g、嫩豆腐135g、西兰花160g、洋葱155g、荞麦饭80g、烹调油6g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','无糖辣椒粉、蒜粉、洋葱粉','蒸/焖','用无糖香辛料腌肉15分钟，蒸或少油焖熟，配菜煮熟；荞麦饭另煮熟或蒸好后同餐食用。',25,520,54.8,45.9,14.5,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(727,364,52,'午餐','禽肉','菌菇去皮鸡腿肉配紫甘蓝杏鲍菇｜荞麦饭','去皮鸡腿肉165g、嫩豆腐110g、紫甘蓝190g、杏鲍菇140g、荞麦饭125g、烹调油4g','荞麦饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','姜片、香菇汁','焖煮','先去皮去骨并切薄，充分加热；食材与菌菇加少量水焖熟，出锅前加少量低盐生抽；荞麦饭另煮熟或蒸好后同餐食用。',30,548,48.2,53.9,17.3,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_poultry.png');
INSERT INTO "meals" VALUES(728,364,52,'晚餐','牛肉','葱姜清蒸牛里脊配茼蒿洋葱｜荞麦面','牛里脊180g、茼蒿160g、洋葱140g、荞麦面125g、烹调油6g','荞麦面','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱姜、少量低盐生抽','蒸','切片腌5分钟；肉和配菜入盘，蒸至熟透；淋葱姜汁；面/魔芋丝煮熟后与菜合碗。',25,514,47.4,46.2,16.1,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_beef.png');
INSERT INTO "meals" VALUES(729,365,53,'午餐','海鲜','清汤虾仁配冬瓜紫甘蓝｜糙米饭','虾仁160g、冬瓜175g、紫甘蓝125g、糙米饭150g、烹调油6g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','葱段、盐少量','煮','清水煮开，按熟化时间下食材，最后放叶菜，清淡调味；糙米饭另煮熟或蒸好后同餐食用。',25,428,36.7,50.3,9.6,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_seafood.png');
INSERT INTO "meals" VALUES(730,365,53,'晚餐','鱼类','椒麻三文鱼配西葫芦荷兰豆｜糙米饭','三文鱼145g、西葫芦175g、荷兰豆125g、糙米饭110g、烹调油4g','糙米饭','低主食需求可将主食减1/3，另加100g非淀粉蔬菜（营养值需重算）','花椒、蒜、少量醋','水煮','鱼肉去刺，彻底做熟；花椒温水浸出味道，煮熟主食材和配菜，少油拌汁；糙米饭另煮熟或蒸好后同餐食用。',25,539,37.5,40.7,24.8,'调料尽量低盐，不加白砂糖；油重已计入热量。',0,'plate_fish.png');
